def mad(values):
    if not values:
        raise ValueError("Input list must not be empty")

    sorted_values = sorted(values)
    n = len(sorted_values)

    if n % 2 == 1:
        median = sorted_values[n // 2]
    else:
        median = (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2

    absolute_differences = [abs(x - median) for x in values]
    sorted_differences = sorted(absolute_differences)
    n_diff = len(sorted_differences)

    if n_diff % 2 == 1:
        mad_value = sorted_differences[n_diff // 2]
    else:
        mad_value = (sorted_differences[n_diff // 2 - 1] + sorted_differences[n_diff // 2]) / 2

    return float(mad_value)

