import calendar

def parse_dmy(text):
    # Remove surrounding spaces
    text = text.strip()

    # Regular expression to match the date format DD.MM.YYYY
    date_pattern = r'^\d{2}\.\d{2}\.\d{4}$'
    if not re.match(date_pattern, text):
        raise ValueError("Invalid date format")

    # Parse the date string
    day, month, year = map(int, text.split('.'))

    # Validate the date
    if not calendar.isleap(year):
        max_days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    else:
        max_days_in_month = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    if day > max_days_in_month[month - 1]:
        raise ValueError("Invalid date")

    return (year, month, day)

