def hms_to_seconds(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")

    if not re.match(r'^\d{2}:\d{2}:\d{2}$', text):
        raise ValueError("Input must be in the format 'HH:MM:SS'.")

    hours, minutes, seconds = map(int, text.split(':'))

    if hours < 0 or hours > 23:
        raise ValueError("Hours must be in the range 00-23.")
    if minutes < 0 or minutes > 59:
        raise ValueError("Minutes must be in the range 00-59.")
    if seconds < 0 or seconds > 59:
        raise ValueError("Seconds must be in the range 00-59.")

    return hours * 3600 + minutes * 60 + seconds

